// Month abbreviation → N+M mapping (months passed + months remaining until Dec)
const monthMap = {
  'jan': '0+12', 'fev': '1+11', 'mar': '2+10', 'abr': '3+9',
  'mai': '4+8', 'jun': '5+7', 'jul': '6+6', 'ago': '7+5',
  'set': '8+4', 'out': '9+3', 'nov': '10+2', 'dez': '11+1'
};

const sheets = $input.first().json.sheets || [];
const result = [];

for (const sheet of sheets) {
  const title = (sheet.properties && sheet.properties.title) ? sheet.properties.title : '';
  // Match tabs that start with 'forecast ' (case-insensitive)
  if (!title.toLowerCase().startsWith('forecast ')) continue;

  // Remove 'forecast ' prefix and parse month + optional suffix
  const rest = title.substring(9).trim(); // e.g. 'ABR' or 'ABR v2'
  const parts = rest.split(/\s+/);
  const monthKey = parts[0].toLowerCase(); // e.g. 'abr'
  const suffix = parts.slice(1).join(' '); // e.g. 'v2' or ''

  const nm = monthMap[monthKey];
  if (!nm) continue; // skip if not a recognized month

  const versionLabel = suffix ? `Forecast ${nm} ${suffix}` : `Forecast ${nm}`;
  result.push({ json: { sheetName: title, versionLabel } });
}

// Sort by month order (0+12 first)
result.sort((a, b) => {
  const na = parseInt(a.json.versionLabel.split('+')[0].replace('Forecast ', ''));
  const nb = parseInt(b.json.versionLabel.split('+')[0].replace('Forecast ', ''));
  return na - nb;
});

return result;

// Accumulate all rows across loop iterations using staticData
if (!$workflow.staticData.accumulatedRows) {
  $workflow.staticData.accumulatedRows = [];
}

// Get the versionLabel from the current batch item in the loop
const versionLabel = $('Loop Over Sheets').first().json.versionLabel;

// Tag each sheet row with _version and accumulate
const taggedRows = $input.all().map(item => ({
  ...item.json,
  _version: versionLabel
}));
$workflow.staticData.accumulatedRows.push(...taggedRows);

// Return the original batch item to feed the loopback
return $('Loop Over Sheets').all();

// Collect all accumulated rows and reset for next run
const rows = $workflow.staticData.accumulatedRows || [];
$workflow.staticData.accumulatedRows = [];
return [{ json: { content: JSON.stringify(rows) } }];
